sys_script_include.script:
var userInfoUtil = Class.create();
userInfoUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUserDetails: function() {
        var result = {};
        var userID = this.getParameter('sysparm_id');
        var grUser = new GlideRecord('sys_user');
        if (grUser.get(userID)) {
            result.phone = grUser.getValue('phone');
            result.manager = grUser.getValue('manager');
            result.email = grUser.getValue('email');
        }
		//gs.info('Alert Employee Data: '+ JSON.stringify(result));
		return JSON.stringify(result);

    },
    type: 'userInfoUtil'
});
